using System.Text.Json;
using System.Text.Json.Serialization;
using PokemonBattle.Engine.Pokemon;

namespace PokemonBattle.Catalog;

/// <summary>
/// Read-only Generation 6 catalog loaded from the JSON embedded in this assembly
/// (generated by backend/tools/catalog-export). Species are limited to Gen 1 for now.
/// </summary>
public sealed class Gen6Catalog
{
    private static readonly Lazy<Gen6Catalog> Loaded = new(Load);

    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        PropertyNameCaseInsensitive = true,
        Converters = { new JsonStringEnumConverter() },
    };

    private readonly IReadOnlyDictionary<string, HashSet<string>> _learnsets;

    private Gen6Catalog(
        IReadOnlyList<SpeciesData> species,
        IReadOnlyList<MoveData> moves,
        IReadOnlyList<AbilityData> abilities,
        IReadOnlyList<ItemData> items,
        IReadOnlyList<NatureData> natures,
        IReadOnlyDictionary<string, HashSet<string>> learnsets,
        TypeChart typeChart)
    {
        Species = species.ToDictionary(s => s.Id);
        Moves = moves.ToDictionary(m => m.Id);
        Abilities = abilities.ToDictionary(a => a.Id);
        Items = items.ToDictionary(i => i.Id);
        Natures = natures.ToDictionary(n => n.Id);
        _learnsets = learnsets;
        TypeChart = typeChart;
    }

    /// <summary>Shared instance, loaded on first use.</summary>
    public static Gen6Catalog Instance => Loaded.Value;

    public IReadOnlyDictionary<string, SpeciesData> Species { get; }
    public IReadOnlyDictionary<string, MoveData> Moves { get; }
    public IReadOnlyDictionary<string, AbilityData> Abilities { get; }
    public IReadOnlyDictionary<string, ItemData> Items { get; }
    public IReadOnlyDictionary<string, NatureData> Natures { get; }
    public TypeChart TypeChart { get; }

    public SpeciesData? FindSpecies(string nameOrId) => Species.GetValueOrDefault(CatalogId.From(nameOrId));
    public MoveData? FindMove(string nameOrId) => Moves.GetValueOrDefault(CatalogId.From(nameOrId));
    public AbilityData? FindAbility(string nameOrId) => Abilities.GetValueOrDefault(CatalogId.From(nameOrId));
    public ItemData? FindItem(string nameOrId) => Items.GetValueOrDefault(CatalogId.From(nameOrId));
    public NatureData? FindNature(string nameOrId) => Natures.GetValueOrDefault(CatalogId.From(nameOrId));

    /// <summary>
    /// Whether the species can legally know the move in Gen 6. Mega Evolutions use the learnset
    /// of their base species.
    /// </summary>
    public bool CanLearn(string species, string move)
    {
        var data = FindSpecies(species);
        if (data is null)
        {
            return false;
        }

        var learnsetId = data.IsMega ? CatalogId.From(data.BaseSpecies) : data.Id;
        return _learnsets.TryGetValue(learnsetId, out var moves) && moves.Contains(LearnsetMoveId(move));
    }

    /// <summary>Every Hidden Power type variant is learned as the single move "hiddenpower".</summary>
    private static string LearnsetMoveId(string move)
    {
        var id = CatalogId.From(move);
        return id.StartsWith(HiddenPower, StringComparison.Ordinal) ? HiddenPower : id;
    }

    private const string HiddenPower = "hiddenpower";

    private static Gen6Catalog Load()
    {
        var chart = Read<TypeChartFile>("typechart");
        var damageTaken = chart.DamageTaken.ToDictionary(
            entry => Enum.Parse<PokemonType>(entry.Key),
            entry => (IReadOnlyDictionary<PokemonType, double>)entry.Value.ToDictionary(
                inner => Enum.Parse<PokemonType>(inner.Key),
                inner => inner.Value));
        var conditionImmunities = chart.ConditionImmunities.ToDictionary(
            entry => Enum.Parse<PokemonType>(entry.Key),
            entry => (IReadOnlySet<TypeCondition>)entry.Value.Select(TypeChart.ToCondition).ToHashSet());

        return new Gen6Catalog(
            Read<List<SpeciesData>>("species"),
            Read<List<MoveData>>("moves"),
            Read<List<AbilityData>>("abilities"),
            Read<List<ItemData>>("items"),
            Read<List<NatureData>>("natures"),
            Read<Dictionary<string, List<string>>>("learnsets").ToDictionary(e => e.Key, e => e.Value.ToHashSet()),
            new TypeChart(damageTaken, conditionImmunities));
    }

    private static T Read<T>(string name)
    {
        var resource = $"gen6/{name}.json";
        using var stream = typeof(Gen6Catalog).Assembly.GetManifestResourceStream(resource)
            ?? throw new InvalidOperationException($"Catalog resource '{resource}' is missing.");
        return JsonSerializer.Deserialize<T>(stream, JsonOptions)
            ?? throw new InvalidOperationException($"Catalog resource '{resource}' is empty.");
    }

    private sealed record TypeChartFile(
        Dictionary<string, Dictionary<string, double>> DamageTaken,
        Dictionary<string, List<string>> ConditionImmunities);
}
